import net.jcip.annotations.GuardedBy;
public class Good1 {
     @GuardedBy("lock")
     private String txt;
     private final Object lock = new Object();

     public String getText() {
         synchronized(lock) {
             return txt; // good
         }
     }
     public String setText(String t) {
         synchronized(lock) {
             txt = t; // good
         }
     }
 }

public class Good2 {
     @GuardedBy("this")
     private String txt;
     private final Object lock = new Object();
     private final Object wrongLock = new Object();

     public String getText() {
         synchronized(this) {
             return txt; // good
         }
     }
     public synchronized String setText(String t) {
             txt = t; // good
     }
 }

